INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Zentralelemente > Mainboard Hauptplatine
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist das Mainboard unabhängig von der Wahl des Prozessors auswählbar?', 2, '[{"text": "Nein", "correct": true, "because": "Sockel und Chipsatz müssen kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Mainboard ohne Berücksichtigung der Arbeitsspeicheranforderungen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "RAM-Typ und Slots sind relevant"}, {"text": "Ja", "correct": false, "because": "Speicheranforderungen beeinflussen Wahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Mainboards immer Erweiterungsmöglichkeiten berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Slots definieren Zukunftssicherheit"}, {"text": "Nein", "correct": false, "because": "Erweiterbarkeit ist oft entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Wahl eines Mainboards unabhängig von der Größe des Gehäuses?', 2, '[{"text": "Nein", "correct": true, "because": "Formfaktor muss zum Gehäuse passen"}, {"text": "Ja", "correct": false, "because": "Größe beeinflusst Kompatibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Mainboard ohne integrierte Schnittstellen ausreichend sein?', 2, '[{"text": "Ja", "correct": true, "because": "Erweiterungskarten können Schnittstellen ergänzen"}, {"text": "Nein", "correct": false, "because": "Abhängig von Anforderungen"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Auswahl eines Mainboards am entscheidendsten?', 3, '[{"text": "Prozessor-Kompatibilität", "correct": true, "because": "Sockel und Chipsatz sind zentral"}, {"text": "Farbe der Platine", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Preis", "correct": false, "because": "Wichtig, aber sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Formfaktor ist für ein Mainboard am häufigsten in Standard-Desktops?', 2, '[{"text": "ATX", "correct": true, "because": "Bietet Balance aus Größe und Erweiterbarkeit"}, {"text": "Micro-ATX", "correct": false, "because": "Kompakter"}, {"text": "Mini-ITX", "correct": false, "because": "Noch kleiner"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente wird direkt durch den Chipsatz des Mainboards bestimmt?', 2, '[{"text": "Unterstützte RAM-Typen", "correct": true, "because": "Chipsatz definiert Speicherunterstützung"}, {"text": "Netzteilleistung", "correct": false, "because": "Unabhängig vom Chipsatz"}, {"text": "Festplattengröße", "correct": false, "because": "Nicht direkt beeinflusst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Anschluss auf dem Mainboard ist für die Stromversorgung primär verantwortlich?', 2, '[{"text": "24-Pin-ATX-Stecker", "correct": true, "because": "Hauptstromversorgung"}, {"text": "SATA-Anschluss", "correct": false, "because": "Für Speichergeräte"}, {"text": "PCIe-Slot", "correct": false, "because": "Für Erweiterungskarten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was limitiert die Anzahl der Erweiterungskarten auf einem Mainboard?', 3, '[{"text": "Anzahl der PCIe-Slots", "correct": true, "because": "Slots definieren Erweiterbarkeit"}, {"text": "Prozessorleistung", "correct": false, "because": "Indirekt relevant"}, {"text": "Netzteilkapazität", "correct": false, "because": "Unterstützend, nicht limitierend"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl eines Mainboards?', 4, '[{"text": "Prozessor-Sockel", "correct": true, "because": "Bestimmt CPU-Kompatibilität"}, {"text": "Formfaktor", "correct": true, "because": "Passt zum Gehäuse"}, {"text": "Anzahl der RAM-Slots", "correct": true, "because": "Beeinflusst Speicherkapazität"}, {"text": "Gewicht der Platine", "correct": false, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können auf einem Mainboard integriert sein?', 3, '[{"text": "USB-Ports", "correct": true, "because": "Standard für Peripherie"}, {"text": "LAN-Anschluss", "correct": true, "because": "Für Netzwerkverbindung"}, {"text": "Audio-Anschlüsse", "correct": true, "because": "Für Soundausgabe"}, {"text": "SCSI-Port", "correct": false, "because": "Veraltet, selten integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind direkt mit dem Mainboard verbunden?', 3, '[{"text": "Prozessor", "correct": true, "because": "Sockel auf Mainboard"}, {"text": "Arbeitsspeicher", "correct": true, "because": "RAM-Slots"}, {"text": "Grafikkarte", "correct": true, "because": "Über PCIe-Slots"}, {"text": "Monitor", "correct": false, "because": "Indirekt über Grafikkarte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines Mainboards auftreten?', 4, '[{"text": "Inkompatibilität mit CPU", "correct": true, "because": "Sockel muss passen"}, {"text": "Zu wenig Erweiterungsslots", "correct": true, "because": "Begrenzt Upgrades"}, {"text": "Unzureichende Stromversorgung", "correct": true, "because": "Braucht passendes Netzteil"}, {"text": "Falsche Farbkombination", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Mainboard zukunftssicher?', 3, '[{"text": "Mehrere PCIe-Slots", "correct": true, "because": "Erlaubt Erweiterungen"}, {"text": "Unterstützung neuer RAM-Standards", "correct": true, "because": "Für spätere Upgrades"}, {"text": "Hohe Anzahl USB-Ports", "correct": true, "because": "Für moderne Peripherie"}, {"text": "Integrierte Grafik", "correct": false, "because": "Optional, nicht zwingend"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Chipsatz des Mainboards bestimmt die Prozessorunterstützung. b) Ein ATX-Mainboard passt in jedes Gehäuse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Chipsatz ja, Gehäusegröße relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Mainboard benötigt einen 24-Pin-ATX-Stecker zur Stromversorgung. b) Die Anzahl der RAM-Slots ist irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "24-Pin ja, RAM-Slots wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) PCIe-Slots erhöhen die Erweiterbarkeit eines Mainboards. b) Jedes Mainboard unterstützt DDR5-RAM.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PCIe ja, DDR5 abhängig vom Chipsatz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Mainboard ohne integrierte Schnittstellen ist unbrauchbar. b) Der Formfaktor beeinflusst die Gehäusekompatibilität.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Schnittstellen ergänzbar, Formfaktor ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Mainboard definiert die maximale RAM-Kapazität. b) Die Wahl des Mainboards ist unabhängig vom Prozessor.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "RAM ja, Prozessor beeinflusst Wahl"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

